249	std::string unsupported_written_warning(
250	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported,
251	    const std::string& engine_id) {
252	  const auto bad = unsupported_written_csrs(st, andes_supported);
253	  if (bad.empty()) return {};
254	  std::string names;
255	  for (const std::string& n : bad) {
256	    if (!names.empty()) names += ", ";
257	    names += n;
258	  }
259	  return "[andesim] warning: the program wrote CSRs engine " + engine_id +
260	         " does not implement: " + names +
261	         " (on this engine's silicon these writes would trap; the hybrid "
262	         "restore skipped them)\n";
263	}
